static constexpr fr poseidon2_fr_from_limbs(const std::array<uint64_t, 4>& canonical,
                                            const std::array<uint64_t, 4>& montgomery) noexcept
{
#if defined(__SIZEOF_INT128__) && !defined(__wasm__)
    (void)canonical;
    return fr(montgomery[0], montgomery[1], montgomery[2], montgomery[3]);
#else
    (void)montgomery;
    return fr(numeric::uint256_t{ canonical[0], canonical[1], canonical[2], canonical[3] });
#endif
}

